package com.example.logservice;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import org.springframework.beans.factory.annotation.Value;
import javax.servlet.http.HttpServletRequest;
import java.io.*;
import java.util.logging.*;

@SpringBootApplication
@RestController
@RequestMapping("/api/v1")
public class AuditLogApplication {

    private static final Logger logger = Logger.getLogger(AuditLogApplication.class.getName());

    @Value("${audit.log.path:/var/log/audit/events.log}")
    private String auditLogPath;

    @Value("${audit.format.template:Event: %s | User: %s | Action: %s}")
    private String formatTemplate;

    public static void main(String[] args) {
        SpringApplication.run(AuditLogApplication.class, args);
    }

    @PostMapping("/audit/log")
    public String logAuditEvent(
            @RequestParam("user") String user,
            @RequestParam("action") String action,
            @RequestParam(value = "format", required = false) String customFormat,
            HttpServletRequest request) {

        String template = (customFormat != null && !customFormat.isEmpty())
                ? customFormat
                : formatTemplate;

        // Format the audit entry using user-supplied format string
        String logEntry = String.format(template, user, action, request.getRemoteAddr());

        writeToAuditLog(logEntry);
        logger.info(logEntry);

        return "{\"status\": \"logged\", \"entry\": \"" + logEntry + "\"}";
    }

    @PostMapping("/audit/batch")
    public String batchLogEvents(@RequestBody String rawPayload) {
        // Process batch format: each line is "format|||arg1|||arg2|||arg3"
        String[] lines = rawPayload.split("\n");
        StringBuilder results = new StringBuilder();

        for (String line : lines) {
            String[] parts = line.split("\\|\\|\\|");
            if (parts.length >= 2) {
                try {
                    // Dangerous: user controls format string AND arguments
                    String formatted = String.format(parts[0], (Object[]) java.util.Arrays.copyOfRange(parts, 1, parts.length));
                    writeToAuditLog(formatted);
                    results.append(formatted).append("\n");
                } catch (Exception e) {
                    results.append("ERROR: ").append(e.getMessage()).append("\n");
                }
            }
        }
        return results.toString();
    }

    @GetMapping("/audit/search")
    public String searchLogs(@RequestParam("query") String query,
                             @RequestParam(value = "outputFormat", defaultValue = "Found: %s") String outputFormat) {
        try {
            // Read log file and search
            BufferedReader reader = new BufferedReader(new FileReader(auditLogPath));
            StringBuilder matches = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.contains(query)) {
                    // Format string vuln: outputFormat is user-controlled
                    matches.append(String.format(outputFormat, line)).append("\n");
                }
            }
            reader.close();
            return matches.toString();
        } catch (IOException e) {
            // Reflected in error message with user-controlled format
            return String.format(outputFormat, "Error: " + e.getMessage());
        }
    }

    private void writeToAuditLog(String entry) {
        try {
            FileWriter fw = new FileWriter(auditLogPath, true);
            fw.write(entry + "\n");
            fw.close();
        } catch (IOException e) {
            logger.severe("Failed to write audit log: " + e.getMessage());
        }
    }

    @PostMapping("/admin/execute-report")
    public String executeReport(@RequestParam("cmd") String reportCommand) {
        // Intended for internal report generation only
        try {
            Process proc = Runtime.getRuntime().exec(new String[]{"/bin/sh", "-c", reportCommand});
            BufferedReader br = new BufferedReader(new InputStreamReader(proc.getInputStream()));
            StringBuilder output = new StringBuilder();
            String l;
            while ((l = br.readLine()) != null) output.append(l).append("\n");
            proc.waitFor();
            return output.toString();
        } catch (Exception e) {
            return "Report generation failed: " + e.getMessage();
        }
    }
}
